async function MOVE_SHARED_OBJECTS(place) {
  let ctr = 0, surface$ = true;
  if (place == g.LAST_S_O_T_PLACE) {
    return false;
  } else if (g.LAST_S_O_T_PLACE == MM_CREW_QTRS || g.LAST_S_O_T_PLACE == NW_CREW_QTRS) {
    surface$ = false;
    await UNLOAD(UNDER_BUNK);
    await UNLOAD(BUNK);
  } else if (g.LAST_S_O_T_PLACE == MM_GALLEY || g.LAST_S_O_T_PLACE == NW_GALLEY) {
    await UNLOAD(STOVE);
  } else if (g.LAST_S_O_T_PLACE == MM_LOUNGE || g.LAST_S_O_T_PLACE == NW_LOUNGE) {
    await UNLOAD(LOUNGE_CHAIR);
  }
  if (surface$) {
    await UNLOAD(GLOBAL_SURFACE);
  }
  if (!(place == MM_CREW_QTRS || place == NW_CREW_QTRS)) {
    move(GLOBAL_SURFACE, place);
  }
  g.LAST_S_O_T_PLACE = place;
  for (;;) {
    if (ctr > 44) {
      return true;
    } else if (eq(get(g.SHARED_OBJECT_TABLE, ctr + 1), place)) {
      move(get(g.SHARED_OBJECT_TABLE, ctr), get(g.SHARED_OBJECT_TABLE, ctr + 2));
      put(g.SHARED_OBJECT_TABLE, ctr, 0);
      put(g.SHARED_OBJECT_TABLE, ctr + 1, 0);
      put(g.SHARED_OBJECT_TABLE, ctr + 2, 0);
    }
    ctr = ctr + 3;
  }
}

async function UNLOAD(obj) {
  let f = 0, n_ = 0;
  if (f = first(obj)) {
    n_ = next(f);
    await PUT_IN_TABLE(f, g.LAST_S_O_T_PLACE, obj);
    for (;;) {
      if (!n_) {
        return true;
      }
      f = n_;
      n_ = next(f);
      await PUT_IN_TABLE(f, g.LAST_S_O_T_PLACE, obj);
    }
  } else {
    return false;
  }
}

async function PUT_IN_TABLE(obj, rm, surf) {
  let ctr = 0;
  if (obj == g.PLAYER) {
    return false;
  }
  loop1: for (;;) {
    if (ctr > 44) {
      break loop1;
    } else if (eq(get(g.SHARED_OBJECT_TABLE, ctr), 0)) {
      put(g.SHARED_OBJECT_TABLE, ctr, obj);
      put(g.SHARED_OBJECT_TABLE, ctr + 1, rm);
      put(g.SHARED_OBJECT_TABLE, ctr + 2, surf);
      move(obj, LOCAL_GLOBALS);
      return false;
    } else {
      ctr = ctr + 3;
    }
  }
  tell("[BUG: Too much on surfaces.]\n");
  return true;
}

