async function TIME_PRINT(num) {
  let hr = 0, pm = false;
  if ((hr = div(num, 60)) > 12) {
    hr = hr - 12;
    pm = true;
  } else if (hr == 12) {
    pm = true;
  } else if (hr == 0) {
    hr = 12;
  }
  printN(hr);
  tell(":");
  if ((hr = mod(num, 60)) < 10) {
    tell("0");
  }
  tell(N(hr), " ");
  tell(S((pm ? "p.m." : "a.m.")));
  return true;
}

