async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0, ctr = 0, per = 0;
  m_f = await MOBY_FIND(tbl);
  if ((m_f > 1) && (obj = getProp(get(tbl, 1), P.GLOBAL))) {
    m_f = 1;
    g.P_MOBY_FOUND = obj;
  }
  if (1 == m_f) {
    if (prso$) {
      if (isVerb(V.TELL) && (g.WINNER == g.PLAYER) && hasFlag(g.P_MOBY_FOUND, VICBIT)) {
        g.P_CONT = false;
        await TELL_NOT_HERE_TALK();
        return true;
      } else if (isVerb(V.EXAMINE)) {
        if (hasFlag(g.P_MOBY_FOUND, PERSON) && !((getProp(await META_LOC(g.PLAYER), P.CORRIDOR) & getProp(loc(g.P_MOBY_FOUND), P.CORRIDOR)) == 0)) {
          tell("You can see ");
          await DPRINT(g.P_MOBY_FOUND);
          tell(" in the distance.\n");
        } else if ((g.PRSO == MCGINTY) && (loc(g.PLAYER) == BACK_ALLEY_2) && (loc(MCGINTY) == MCGINTY_HQ)) {
          tell("Looking through the window, you see ");
          await DPRINT(MCGINTY);
          tell(" in his office.\n");
        } else {
          await GLOBAL_NOT_HERE_PRINT(g.PRSO);
        }
        return true;
      } else {
        g.PRSO = g.P_MOBY_FOUND;
      }
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    if (g.P_XADJ && !g.P_XNAM) {
      g.P_NONOUN = true;
    } else {
      g.P_NONOUN = false;
    }
    return false;
  } else if (!prso$) {
    if (isVerb(V.ASK_ABOUT) || (isVerb(V.TELL) && (g.PRSO == ME))) {
      if (g.PRSO == ME) {
        if ((g.WINNER == g.PLAYER) && g.QCONTEXT && (g.HERE == g.QCONTEXT_ROOM)) {
          per = g.QCONTEXT;
        } else {
          per = g.WINNER;
        }
      } else {
        per = g.PRSO;
      }
      if (hasFlag(per, VICBIT)) {
        await SAY_CONFUSED(per, prso$);
      } else {
        await SUDDENLY_REALIZE_TALKING(per);
      }
      return true;
    } else if (hasFlag(g.PRSO, VICBIT)) {
      return await SAY_CONFUSED(g.PRSO, prso$);
    } else {
      tell("You wouldn't find any");
      await NOT_HERE_PRINT(prso$);
      tell(" there.\n");
      return true;
    }
  } else {
    return NOT_HERE_OBJECT;
  }
}

