async function CLOCKER() {
  let c_ = 0, e = 0, tick = 0, flg = false, val = 0;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.PRESENT_TIME = g.PRESENT_TIME + 1;
  if (g.PRESENT_TIME > 1439) {
    g.PRESENT_TIME = g.PRESENT_TIME - 1440;
  }
  if (g.WATCH_WOUND) {
    if ((g.WATCH_MOVES = g.WATCH_MOVES + 1) > 59) {
      g.WATCH_MOVES = g.WATCH_MOVES - 60;
      if ((g.WATCH_SCORE = g.WATCH_SCORE + 1) > 11) {
        g.WATCH_SCORE = 0;
      }
    }
  }
  await WATCH_UPDATE();
  c_ = g.C_TABLE + g.C_INTS;
  e = g.C_TABLE + C_TABLELEN;
  for (;;) {
    if (c_ == e) {
      return flg;
    } else if (!(get(c_, C_ENABLED$) == 0)) {
      tick = get(c_, C_TICK);
      if (tick == 0) {
      } else {
        put(c_, C_TICK, tick - 1);
        if (!(tick > 1) && (val = await apply(get(c_, C_RTN)))) {
          if (!flg || (val == M_FATAL)) {
            flg = val;
          }
        }
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function WATCH_UPDATE() {
  if (loc(WATCH) == g.PLAYER) {
    g.MOVES = g.WATCH_MOVES;
    return g.SCORE = g.WATCH_SCORE;
  } else {
    g.MOVES = 99;
    return g.SCORE = 111;
  }
}

async function GO() {
  restart: for (;;) {
    putb(g.P_LEXV, 0, 59);
    enable(await QUEUE(I_UNWOUND.id, 20));
    enable(await QUEUE(I_BUSINESS_HOURS.id, 60));
    enable(await QUEUE(I_FERRY_APPROACHING.id, 117));
    enable(await QUEUE(I_FERRY.id, 120));
    enable(await QUEUE(I_HUNGER.id, 15));
    enable(await QUEUE(I_THIRST.id, 25));
    enable(await QUEUE(I_TIRED.id, 929));
    enable(await QUEUE(I_LIVER.id, 10));
    await QUEUE(I_DRILL.id, 5);
    await QUEUE(I_MM_COMPRESSOR.id, 80);
    enable(await QUEUE(I_PLOT_NEVER_STARTS.id, 60));
    g.LIT = true;
    g.SCORE = 8;
    g.WINNER = ADVENTURER;
    g.PLAYER = g.WINNER;
    g.SAMPLE_TREASURE = GLOBAL_OBJECTS;
    await PUT_IN_TABLE(ENVELOPE, MCGINTY_HQ, GLOBAL_SURFACE);
    g.HERE = BEDROOM;
    g.P_IT_OBJECT = false;
    if (!(hasFlag(g.HERE, TOUCHBIT))) {
      await START_MOVEMENT();
      await TELL_START_STR();
      crlf();
      await V_VERSION();
      crlf();
    }
    move(g.WINNER, BED);
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

