  if (g.P_LEN == 0) {
    tell("What?\n");
    return false;
  } else if (eq(word = get(g.P_LEXV, ptr), W.WHY, W.HOW, W.WHEN) || (word == W.IS || word == W.DID || word == W.ARE)) {
    tell("Sorry, but this program can't handle questions like that. You should stick to questions like \"WHAT IS ...\" and \"WHERE IS ....\" Maybe you'd like to reread the manual.\n");
    return false;
  }
  len = g.P_LEN;
  g.P_DIR = false;
