async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true, _2nd = false;
  if (f = first(obj)) {
    if (!(next(f))) {
      g.P_IT_OBJECT = f;
    }
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
        _2nd = true;
      } else {
        if (n_ || !_2nd) {
          _2nd = false;
          tell(",");
        }
        tell(" ");
        if (!n_) {
          tell("and ");
        }
      }
      await APRINT(f);
      f = n_;
      if (!f) {
        return true;
      }
    }
  } else {
    return false;
  }
}

