async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      if (!(hasFlag(x, WORNBIT))) {
        cnt = cnt + 1;
      }
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if (cont = first(obj)) {
    loop1: for (;;) {
      if ((obj == g.WINNER) && hasFlag(cont, WEARBIT)) {
        wt = wt + 1;
      } else {
        wt = wt + (await WEIGHT(cont));
      }
      if (!(cont = next(cont))) {
        break loop1;
      }
    }
  }
  return wt + getProp(obj, P.SIZE);
}

