async function V_WAIT(num = 10, not_int$ = true, who = false) {
  let interrupted = false;
  if (not_int$) {
    await TELL_PASSES();
    if (g.I_WAIT_DURATION > 0) {
      return false;
    }
  }
  loop1: for (;;) {
    if ((num = num - 1) < 0) {
      break loop1;
    } else if (await CLOCKER()) {
      interrupted = true;
      break loop1;
    } else if (who && (loc(who) == g.HERE)) {
      interrupted = true;
      break loop1;
    }
  }
  if (not_int$) {
    return g.CLOCK_WAIT = true;
  } else {
    return interrupted;
  }
}

async function V_WAIT_FOR() {
  if (g.PRSO == INTNUM) {
    if (g.P_NUMBER > 180) {
      tell("That's too long to wait.\n");
      return true;
    } else {
      return await V_WAIT(g.P_NUMBER);
    }
  } else if (g.PRSO == ME || g.PRSO == g.PLAYER) {
    tell("You're already here!\n");
    return true;
  } else if (hasFlag(g.PRSO, PERSON) || (g.PRSO == DELIVERY_BOY)) {
    if (loc(g.PRSO) == g.HERE) {
      tell("He's already here!\n");
      return true;
    } else {
      await TELL_PASSES();
      loop1: for (;;) {
        if (await V_WAIT(30, false, g.PRSO)) {
          if (loc(g.PRSO) == g.HERE) {
            setFlag(g.PRSO, TOUCHBIT);
            await START_SENTENCE(g.PRSO);
            tell(", for whom you were waiting, has arrived.\n");
            g.P_IT_OBJECT = g.PRSO;
            break loop1;
          }
        }
        await START_SENTENCE(g.PRSO);
        tell(" isn't here yet. Do you want to keep waiting? (YES or NO?)");
        if (!(await YES$())) {
          tell("If you say so...\n");
          break loop1;
        }
      }
      return g.CLOCK_WAIT = true;
    }
  } else if (hasFlag(g.PRSO, VICBIT)) {
    tell("I don't think he's going anywhere.\n");
    return true;
  } else {
    tell("Why? It's not going anywhere.\n");
    return true;
  }
}

