async function V_BUY(rent = false) {
  let cost = 0;
  if (!(loc(g.PRSO) == ROOMS) && (cost = getProp(g.PRSO, P.NORTH)) && (cost > 0)) {
    if ((await ENABLED$(I_EQUIP.id)) && !(loc(MCGINTY) == OUTFITTERS_HQ)) {
      tell("The salesman is too busy with Johnny right now.\n");
      return true;
    } else if (hasFlag(g.PRSO, RENTBIT) && !rent) {
      tell("That's not for sale, but you might try renting it.\n");
      return true;
    } else if (cost > g.POCKET_CHANGE) {
      return await TELL_NO_AFFORD();
    } else {
      g.POCKET_CHANGE = g.POCKET_CHANGE - cost;
      putProp(g.PRSO, P.NORTH, -1);
      if (g.JOHNNY_MADE_DEAL && !g.DELIVERY_MADE) {
        setFlag(g.PRSO, TRYTAKEBIT);
        put(g.DELIVERY_TABLE, g.DT_PTR, g.PRSO);
        g.DT_PTR = g.DT_PTR + 2;
      } else {
        setFlag(g.PRSO, TAKEBIT);
        clearFlag(g.PRSO, NDESCBIT);
        if ((((await WEIGHT(g.PRSO)) + (await WEIGHT(g.WINNER))) > g.LOAD_ALLOWED) || ((await CCOUNT(g.WINNER)) > g.FUMBLE_NUMBER)) {
          move(g.PRSO, GLOBAL_SURFACE);
        } else {
          move(g.PRSO, g.WINNER);
        }
      }
      tell("You have ");
      if (rent) {
        tell("rented");
      } else {
        tell("purchased");
      }
      tell(" ");
      await APRINT(g.PRSO);
      tell(" for $", N(cost));
      if (loc(g.PRSO) == GLOBAL_SURFACE) {
        tell(". Since you can't currently carry it, the salesman leaves it on the counter");
      }
      tell(".\n");
      return true;
    }
  } else if (cost == (-1)) {
    if (hasFlag(g.PRSO, RENTBIT)) {
      tell("You've already rented it.\n");
      return true;
    } else {
      return (await TELL_ONLY_ONCE("had to buy"));
    }
  } else if (g.PRSO == DRINKING_WATER) {
    if (g.HERE == MM_GALLEY || g.HERE == NW_GALLEY) {
      tell("Get it ");
      await DPRINT(GLOBAL_SELF);
      tell(".\n");
      return true;
    } else {
      await PERFORM(V.ASK_FOR, SPEAR_CARRIER, DRINKING_WATER);
      g.P_IT_OBJECT = DRINKING_WATER;
      return true;
    }
  } else {
    tell("That's not for sale.\n");
    return true;
  }
}

