async function FIND_IN(where, what) {
  let w_ = 0, r = false;
  w_ = first(where);
  if (!w_) {
    return false;
  }
  loop1: for (;;) {
    if (hasFlag(w_, what)) {
      if (r) {
        return M_FATAL;
      } else {
        r = w_;
      }
    } else if (!(w_ = next(w_))) {
      break loop1;
    }
  }
  return r;
}

