async function AIR_TANK_F() {
  if (isVerb(V.EXAMINE)) {
    tell("This double tank made of aluminum is designed to fit over a ");
    await DPRINT(WET_SUIT);
    tell(". Its gauge is currently at ");
    if (g.AIR_LEFT > 150) {
      tell("full");
    } else if (g.AIR_LEFT > 100) {
      tell("fairly full");
    } else if (g.AIR_LEFT > 50) {
      tell("medium");
    } else if (g.AIR_LEFT > 15) {
      tell("almost empty");
    } else {
      tell("empty");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.FILL)) {
    if ((g.PRSI == COMPRESSOR) || ((g.PRSI == AIR) && (loc(COMPRESSOR) == g.HERE))) {
      if (getProp(COMPRESSOR, P.NORTH) > 0) {
        tell("The salesman tells you to rent the compressor first.\n");
        return true;
      } else if (hasFlag(AIR_TANK, WORNBIT)) {
        return await TELL_CONTORT();
      } else {
        g.AIR_LEFT = 160;
        return (await TELL_NOW(AIR_TANK, "filled"));
      }
    } else if (g.PRSI == MM_COMPRESSOR) {
      tell("There's no way to get air from this compressor to the tank.\n");
      return true;
    } else if (g.PRSI == AIR) {
      tell("The right compressor would probably help.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EMPTY)) {
    if (eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C)) {
      return (await JIGS_UP("Not a very good idea..."));
    } else if (g.AIR_LEFT == 0) {
      return (await TELL_ALREADY("empty"));
    } else {
      g.AIR_LEFT = 0;
      return (await TELL_NOW(AIR_TANK, "empty"));
    }
  } else if (isVerb(V.WEAR)) {
    if (hasFlag(WET_SUIT, WORNBIT)) {
      return false;
    } else if (hasFlag(DEEP_SUIT, WORNBIT)) {
      tell("This tank can't be worn with a ");
      await DPRINT(DEEP_SUIT);
      tell(".\n");
      return true;
    } else {
      tell("This tank should be worn outside a ");
      await DPRINT(WET_SUIT);
      tell(".\n");
      return true;
    }
  } else if (eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C) && isVerb(V.DROP, V.THROW) && !(hasFlag(DEEP_SUIT, WORNBIT)) && !(await AIRTIGHT_ROOM$())) {
    return (await JIGS_UP("As the tank falls away, it pulls the airhose with it, making you regret your lack of gills."));
  } else {
    return false;
  }
}

