async function POINT_LOOKOUT_F(rarg) {
  if (rarg == M_ENTER) {
    if ((g.MEETINGS_COMPLETED == 2) && (g.PRESENT_TIME < 660)) {
      return enable(await QUEUE(I_THIRD_MEETING.id, -1));
    } else {
      return false;
    }
  } else if (rarg == M_BEG) {
    if (isVerb(V.LEAP)) {
      return (await JIGS_UP("Your pleasant leap is interrupted as you find yourself impaled on the jagged rocks."));
    } else if ((g.TM_CTR > 0) && (g.TM_CTR < 6)) {
      if (isVerb(V.YES)) {
        tell("\"That's nice, but I'd like to see it.\"\n");
        return true;
      } else if (isVerb(V.NO)) {
        g.TM_CTR = 4;
        return await I_THIRD_MEETING();
      } else if (isVerb(V.WALK)) {
        tell("Johnny puts a hand on your shoulder. \"Not so fast, matey.\"\n");
        return true;
      } else if (isVerb(V.SHOW) && (g.PRSI == JOHNNY)) {
        if (((g.PRSO == GLOBAL_MONEY) || ((g.PRSO == INTNUM) && g.P_DOLLAR_FLAG)) && (hasFlag(WET_SUIT, WORNBIT) || hasFlag(DEEP_SUIT, WORNBIT))) {
          (await TELL_CANT_REACH("your money"));
          return true;
        }
        if (g.PRSO == GLOBAL_MONEY) {
          g.P_AMOUNT = 0;
        }
        if (((g.PRSO == GLOBAL_MONEY) && (g.POCKET_CHANGE > 499)) || ((g.PRSO == INTNUM) && g.P_DOLLAR_FLAG && (g.P_AMOUNT > 499) && !(g.P_AMOUNT > g.POCKET_CHANGE))) {
          g.TM_CTR = 5;
          tell("He smiles and flashes a wad that represents the contributions of your three partners.\n");
          return true;
        } else if ((g.PRSO == GLOBAL_MONEY) || ((g.PRSO == INTNUM) && g.P_DOLLAR_FLAG)) {
          if (g.P_AMOUNT > g.POCKET_CHANGE) {
            tell("You haven't got that much to show him.\n");
            return true;
          } else {
            return (await JIGS_UP("Johnny looks disappointed. \"We need at least $500 from you. I hate to do this, but you might tell McGinty...\" Suddenly you feel a shove in the back and see the pointy rocks below rush up to meet your descent."));
          }
        } else {
          return false;
        }
      } else if (isVerb(V.GIVE) && (g.PRSI == JOHNNY)) {
        if (g.PRSO == GLOBAL_MONEY) {
          g.P_AMOUNT = 0;
        }
        if (((g.PRSO == GLOBAL_MONEY) && (g.POCKET_CHANGE > 499)) || ((g.PRSO == INTNUM) && g.P_DOLLAR_FLAG && (g.P_AMOUNT > 499) && !(g.P_AMOUNT > g.POCKET_CHANGE))) {
          if (!(hasFlag(DEEP_SUIT, WORNBIT)) && !(hasFlag(WET_SUIT, WORNBIT))) {
            tell("Johnny examines your money and returns it. \"You hold it. I needed to make sure you had it.\" ");
          }
        }
        if ((g.PRSO == GLOBAL_MONEY) || ((g.PRSO == INTNUM) && g.P_DOLLAR_FLAG)) {
          if (g.P_AMOUNT > g.POCKET_CHANGE) {
            return (await TELL_YOU_CANT("give him more than you've got."));
          } else {
            await PERFORM(V.SHOW, g.PRSO, JOHNNY);
            return true;
          }
        } else {
          return false;
        }
      } else {
        return false;
      }
    } else if (g.TM_CTR == 7) {
      if (isVerb(V.YES)) {
        g.SHIP_CHOSEN = SALVAGER;
        g.TM_CTR = 8;
        return true;
      } else if (isVerb(V.NO)) {
        g.SHIP_CHOSEN = TRAWLER;
        g.TM_CTR = 8;
        return true;
      } else if (isVerb(V.MAYBE)) {
        tell("\"A wise guy, huh?\" ");
        return true;
      } else if (isVerb(V.WALK)) {
        tell("\"Let's finish here first, huh?\" ");
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

