async function DETECTOR_COMPARTMENT_F(rarg = false) {
  if (rarg == M_CONT) {
    if (isVerb(V.TAKE) && (g.PRSO == DRY_CELL)) {
      if (await ITAKE()) {
        tell("Taken.\n");
        if (g.DETECTOR_POWERED) {
          g.DETECTOR_POWERED = false;
        }
      }
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    if (hasFlag(DETECTOR_COMPARTMENT, OPENBIT)) {
      tell("The compartment is on the side of the machine. Inside ");
      if (first(DETECTOR_COMPARTMENT)) {
        tell("is a connected");
      } else {
        tell("are connections for a");
      }
      tell(" nine-volt ");
      await DPRINT(DRY_CELL);
      tell(".\n");
    } else {
      (await TELL_CLOSED("small panel on the side of the machine"));
    }
    return true;
  } else if (isVerb(V.PUT)) {
    if (g.PRSO == DETECTOR_COMPARTMENT) {
      return false;
    } else if (!(hasFlag(DETECTOR_COMPARTMENT, OPENBIT))) {
      return (await TELL_CLOSED("panel"));
    } else if (g.PRSO == DRY_CELL) {
      move(DRY_CELL, DETECTOR_COMPARTMENT);
      if (!(hasFlag(DRY_CELL, RMUNGBIT))) {
        g.DETECTOR_POWERED = true;
      }
      tell("The ");
      await DPRINT(DRY_CELL);
      tell(" fits snugly inside.\n");
      return true;
    } else {
      tell("Unfortunately, it doesn't fit.\n");
      return true;
    }
  } else if (isVerb(V.OPEN) && (loc(DRY_CELL) == DETECTOR_COMPARTMENT) && eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C) && !(await AIRTIGHT_ROOM$())) {
    setFlag(DRY_CELL, RMUNGBIT);
    g.DETECTOR_POWERED = false;
    return false;
  } else if (isVerb(V.EMPTY) && hasFlag(DETECTOR_COMPARTMENT, OPENBIT)) {
    g.DETECTOR_POWERED = false;
    return false;
  } else {
    return false;
  }
}

