async function DRILL_F(rarg = false) {
  if (rarg == M_CONT) {
    if (isVerb(V.TAKE) && (g.PRSO == BATTERY)) {
      if (await ITAKE()) {
        tell("Taken.");
        if (g.DRILL_POWERED) {
          g.DRILL_POWERED = false;
          if (g.DRILL_ON) {
            disable(await INT(I_DRILL.id));
            tell(" The drill bit winds to a halt.");
          }
        }
        crlf();
      }
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.LAMP_ON) && (g.PRSO == DRILL)) {
    if (g.DRILL_ON) {
      return (await TELL_ALREADY("on"));
    } else if (g.DRILL_POWERED) {
      g.DRILL_ON = true;
      enable(await INT(I_DRILL.id));
      tell("The drill bit begins to spin.\n");
      return true;
    } else {
      g.DRILL_ON = true;
      return (await TELL_SWITCH("on"));
    }
  } else if (isVerb(V.LAMP_OFF) && (g.PRSO == DRILL)) {
    if (!g.DRILL_ON) {
      return (await TELL_ALREADY("off"));
    } else if (g.DRILL_POWERED) {
      g.DRILL_ON = false;
      disable(await INT(I_DRILL.id));
      tell("The drill bit stops spinning.\n");
      return true;
    } else {
      g.DRILL_ON = false;
      return (await TELL_SWITCH("off"));
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("This waterproof wonder features a permanent bit");
    if (await QUEUED$(I_DRILL.id)) {
      tell(" which is turning");
    }
    tell(", a panel which is ");
    if (hasFlag(DRILL, OPENBIT)) {
      tell("open");
      if (g.DRILL_POWERED) {
        tell(" with a C battery inside");
      } else {
        tell(", revealing space for a C battery");
      }
    } else {
      tell("closed");
    }
    tell(", and a switch which is in the \"");
    if (g.DRILL_ON) {
      tell("on");
    } else {
      tell("off");
    }
    tell("\" position.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    await PERFORM(V.EXAMINE, DRILL);
    return true;
  } else if (isVerb(V.OPEN) && (g.PRSO == DRILL) && (loc(BATTERY) == DRILL) && eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C) && !(await AIRTIGHT_ROOM$())) {
    setFlag(BATTERY, RMUNGBIT);
    g.DRILL_POWERED = false;
    return false;
  } else if (g.PRSI == DRILL) {
    if (isVerb(V.PUT)) {
      if (!(hasFlag(DRILL, OPENBIT))) {
        g.P_IT_OBJECT = DRILL;
        return (await TELL_CLOSED("panel"));
      } else if (g.PRSO == BATTERY) {
        move(BATTERY, DRILL);
        if (hasFlag(BATTERY, RMUNGBIT)) {
          (await TELL_NOW(BATTERY, "in the drill"));
          return true;
        }
        g.DRILL_POWERED = true;
        if (g.DRILL_ON) {
          enable(await INT(I_DRILL.id));
          tell("The drill bit starts spinning.\n");
          return true;
        } else {
          return (await TELL_NOW(BATTERY, "in the drill"));
        }
      } else {
        return await TELL_NO_FIT();
      }
    } else if (isVerb(V.TAKE, V.ASK_ABOUT, V.TELL, V.PUT_AGAINST, V.PUT_ON)) {
      return false;
    } else if ((!g.DRILL_ON || !g.DRILL_POWERED) && !(g.PRSO == GLOBAL_TIME)) {
      g.P_IT_OBJECT = DRILL;
      tell("The ");
      await DPRINT(DRILL);
      tell(" isn't running!\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

