async function UNDERWATER_U(print$ = true) {
  let l = 0;
  if (!print$) {
    return false;
  }
  g.DEPTH = g.DEPTH - 50;
  if (!(loc(SAFETY_LINE) == (l = loc(WEASEL))) && !(loc(TREASURE_CHEST) == l) && !(loc(EMPTY_CHEST) == l)) {
    clearFlag(LINE_HACK, INVISIBLE);
  }
  if (g.DEPTH == 0) {
    tell("You get out of the water and reboard your ship...\n\n");
    disable(await INT(I_AIR_SUPPLY.id));
    if (await ENABLED$(I_LAST_GASP.id)) {
      disable(await INT(I_LAST_GASP.id));
    } else {
      disable(await INT(I_MM_COMPRESSOR.id));
    }
    if (hasFlag(OCEAN_FLOOR, TOUCHBIT) || hasFlag(WRECK_1, TOUCHBIT)) {
      await RATING_UPD(25);
      if ((loc(SAFETY_LINE) == TREASURE_CHEST) || ((loc(GLASS_CASE) == g.PLAYER) && !(hasFlag(STAMPS, RMUNGBIT)))) {
        await RATING_UPD(25);
        if (loc(TREASURE_CHEST) == loc(WEASEL)) {
          await TREASURE_CHEST_WIN();
        } else if (loc(SAFETY_LINE) == TREASURE_CHEST) {
          await CHEST_PULL_UP();
          await TREASURE_CHEST_WIN();
        } else {
          tell("When your shipmates find that you've recovered these priceless stamps, they congratulate you. ");
        }
        if (g.WEASEL_BLOWN || hasFlag(ENVELOPE, INVISIBLE)) {
          tell("Johnny slaps you on the back. \"Good job, matey!\" As you return to the island over the calm, dazzling blue sea, you contemplate your wealth with a touch of sadness. You think of Hevlin and hope his soul is resting a little easier now.\n\n");
          await RATING_UPD(20);
          await V_SCORE();
          return await quit();
        } else {
          tell("Exhilarated but tired, you lie out on the deck. You fall asleep at once, and dream of a tropical paradise. But even as you dream, your throat is cut! And as your life drains away, you realize how foolish it was not to have suspected a traitor!\n");
          return await FINISH();
        }
      } else if ((loc(GLASS_CASE) == g.PLAYER) && hasFlag(STAMPS, RMUNGBIT)) {
        tell("But their elation turns to disappointment, as they notice that the stamps are waterlogged and, thus, worthless");
        return await LONG_TRIP();
      } else if (loc(EMPTY_CHEST) == loc(WEASEL)) {
        return await EMPTY_CHEST_LOSE();
      } else if (loc(SAFETY_LINE) == EMPTY_CHEST) {
        await CHEST_PULL_UP();
        return await EMPTY_CHEST_LOSE();
      } else {
        tell("When your shipmates find out that you haven't found any treasure, Johnny shakes his head. You can't help feeling you've let them, as well as ");
        await DPRINT(GLOBAL_SELF);
        tell(", down");
        return await LONG_TRIP();
      }
    } else if (g.AT_SEA && (g.PRESENT_TIME > 720)) {
      tell("Johnny looks downcast when he sees that you empty-handed. \"Let's get back to the Island. Maybe another time...\"\n");
      return await FINISH();
    } else if (g.SHIP_CHOSEN == TRAWLER) {
      setFlag(OCEAN, VEHBIT);
      move(LINE_HACK, NW_AFT_DECK);
      return NW_AFT_DECK;
    } else {
      setFlag(OCEAN, VEHBIT);
      move(LINE_HACK, MM_AFT_DECK);
      return MM_AFT_DECK;
    }
  } else {
    tell("You ascend ");
    if (g.HERE == UNDERWATER) {
      tell("another ");
    }
    tell("50 feet...\n\n");
    if (g.DOOMED && (g.DEPTH == 250)) {
      return (await JIGS_UP("You suddenly find yourself inhaling water! The airhose trailing behind must have torn, and there's no time to do anything about it!"));
    } else {
      return UNDERWATER;
    }
  }
}

