async function UNDERWATER_D(print$ = true) {
  if (!print$) {
    return false;
  }
  g.DEPTH = g.DEPTH + 50;
  if ((g.DEPTH > 300) && !(hasFlag(DEEP_SUIT, WORNBIT))) {
    return (await JIGS_UP("As you descend further, Merv Griffin swims by, offering you Pittsburgh Penguin tickets. You realize too late that this is a hallucination, since Merv doesn't even like the Penguins. At this depth, narcosis takes over, and all that's left is to say bye to Merv..."));
  } else if (g.DEPTH == g.OCEAN_BOTTOM) {
    if (g.WRECK_CHOSEN) {
      tell("The yellow beam from your light settles on a huge jagged outcropping of rusted metal and barnacles. As you angle your light downward, you can barely make out the shape of a monstrous corroded hull, partly buried in the silt from its decades of slumber on the floor of the ocean.\n\n");
      return WRECK_1;
    } else {
      tell("You flutter down to the ocean floor...\n\n");
      return OCEAN_FLOOR;
    }
  } else {
    tell("You descend another 50 feet...\n\n");
    return UNDERWATER;
  }
}

