async function ROPE_F(rarg = false) {
  if (rarg == M_OBJDESC) {
    if (hasFlag(ROPE, TAKEBIT)) {
      tell("A length of rope lies here.");
    } else {
      tell("A rope hangs down here.");
    }
    return crlf();
  } else if (isVerb(V.CUT)) {
    if (g.PRSI == SWORD) {
      if (g.ROPE_HANGING) {
        setFlag(ROPE, TAKEBIT);
        g.ROPE_HANGING = false;
        tell("A three-foot length of rope falls to the deck.\n");
        return true;
      } else if (hasFlag(ROPE, NDESCBIT)) {
        if (loc(g.PLAYER) == CASK) {
          g.ROPE_HANGING = true;
          clearFlag(ROPE, NDESCBIT);
          await RATING_UPD(15);
          tell("The rope falls to within eight feet of the floor.\n");
          return true;
        } else {
          return await TELL_ROPE_HIGH();
        }
      } else {
        move(ROPE, LOCAL_GLOBALS);
        tell("You chop the rope into many small pieces, which float off on the current and become lost among the debris.\n");
        return true;
      }
    } else {
      return (await TELL_YOU_CANT("cut it with that."));
    }
  } else if (!g.ROPE_HANGING) {
    if (isVerb(V.RUB, V.MOVE, V.UNTIE, V.CLIMB_FOO, V.TAKE)) {
      if (hasFlag(ROPE, TAKEBIT)) {
        return false;
      } else {
        return await TELL_ROPE_HIGH();
      }
    } else {
      return false;
    }
  } else if (isVerb(V.TAKE)) {
    tell("It's tied securely above.\n");
    return true;
  } else if (isVerb(V.CLIMB_FOO)) {
    await DO_WALK(P.UP);
    g.P_IT_OBJECT = ROPE;
    return true;
  } else if (isVerb(V.UNTIE)) {
    return (await TELL_CANT_REACH("the top knot"));
  } else {
    return false;
  }
}

