async function FALLEN_BUNK_F() {
  if (isVerb(V.PUSH)) {
    tell("The bunks move a bit but fall back to where they were.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (g.BUNKS_MOVED) {
      tell("A ");
      await DPRINT(FALLEN_BUNK);
      tell(" teeters by the passageway.");
      if (loc(IRON_BAR) == FALLEN_BUNK) {
        tell(" They are being held up by an ");
        await DPRINT(IRON_BAR);
        tell(".");
      }
      return crlf();
    } else {
      tell("There is a ");
      await DPRINT(FALLEN_BUNK);
      tell(" before the aft doorway.\n");
      return true;
    }
  } else if (isVerb(V.SLEEP)) {
    return await TELL_BAD_SHAPE();
  } else if (isVerb(V.MOVE)) {
    if (g.PRSI == IRON_BAR) {
      if (g.BUNKS_MOVED) {
        tell("They've already been moved.\n");
        return true;
      } else {
        g.BUNKS_MOVED = true;
        enable(await QUEUE(I_PLUMMET.id, 2));
        g.CRIMP_CTR = 0;
        tell("Using the ");
        await DPRINT(IRON_BAR);
        tell(", you move the bunks out of the way.\n");
        return true;
      }
    } else {
      tell("They're too heavy to move ");
      if (g.PRSI) {
        tell("that way");
      } else {
        tell("by hand");
      }
      tell(".\n");
      return true;
    }
  } else if (isVerb(V.LOOK_BEHIND) && (g.HERE == WRECK_7) && !g.BUNKS_MOVED) {
    tell("There is a passageway there.\n");
    return true;
  } else if (g.BUNKS_MOVED && isVerb(V.PUT_UNDER) && (g.PRSO == IRON_BAR)) {
    disable(await INT(I_PLUMMET.id));
    move(IRON_BAR, FALLEN_BUNK);
    putProp(WRECK_7, P.DESCFCN, 65);
    putProp(WRECK_8, P.DESCFCN, 65);
    tell("The ");
    await DPRINT(IRON_BAR);
    tell(" is wedging the bunks up.\n");
    return true;
  } else if (isVerb(V.LOOK_UNDER) && (loc(IRON_BAR) == FALLEN_BUNK)) {
    tell("The ");
    await DPRINT(IRON_BAR);
    tell(" is there,", S(g.WEDGED_STR), "\n");
    return true;
  } else {
    return false;
  }
}

