async function GLASS_CASE_F() {
  if (isVerb(V.OPEN)) {
    tell("It's sealed shut.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The ");
    await DPRINT(GLASS_CASE);
    tell(" has a shelf inside it. A collection of extremely rare ");
    if (hasFlag(STAMPS, RMUNGBIT)) {
      tell("but soggy ");
    }
    tell("postage stamps sits on the shelf. There is a crack near a bottom corner of the case");
    if (loc(PUTTY) == GLASS_CASE) {
      tell(", which is sealed with putty");
    }
    tell(".");
    if ((loc(HOLE_1) == GLASS_CASE) || (loc(HOLE_2) == GLASS_CASE)) {
      tell(" Near the crack is the hole you drilled");
      if ((loc(PUTTY) == GLASS_CASE) && !g.NO_HOLE_PLUGGED) {
        tell(", which is also filled with putty");
      }
      tell(".");
    }
    if (g.WATER_IN_CASE > 0) {
      tell(" The case has some water in it.");
    }
    return crlf();
  } else if ((isVerb(V.POUR, V.TAKE) && (g.PRSO == OCEAN)) || isVerb(V.EMPTY)) {
    if (g.WATER_IN_CASE == 0) {
      tell("There's no water in the case.\n");
      return true;
    } else if (!(await AIRTIGHT_ROOM$())) {
      tell("That would be a losing battle.\n");
      return true;
    } else {
      g.WATER_IN_CASE = 0;
      setFlag(STAMPS, RMUNGBIT);
      tell("In the process of emptying the case, you manage to get the stamps wet.\n");
      return true;
    }
  } else if (isVerb(V.DRILL)) {
    if ((loc(g.PLAYER) == WRECK_5) && !g.WRECK_5_FLOODED) {
      g.WATER_IN_CASE = 0;
      tell("The water pours out of the hole.\n");
    } else {
      g.WATER_IN_CASE = 10;
      disable(await INT(I_CASE_LEAK.id));
      setFlag(STAMPS, RMUNGBIT);
      tell("Water pours into the case, ruining the stamps.\n");
    }
    return await ADD_HOLE(GLASS_CASE);
  } else if (isVerb(V.MUNG) && (g.PRSO == GLASS_CASE)) {
    tell("That wouldn't be too smart.\n");
    return true;
  } else {
    return false;
  }
}

