async function LOCKER_DOOR_F() {
  if (isVerb(V.OPEN)) {
    if (hasFlag(LOCKER_DOOR, OPENBIT)) {
      return (await TELL_ALREADY("open"));
    } else {
      setFlag(LOCKER_DOOR, OPENBIT);
      return (await TELL_NOW(LOCKER_DOOR, "open"));
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(LOCKER_DOOR, OPENBIT)) {
      clearFlag(LOCKER_DOOR, OPENBIT);
      return (await TELL_NOW(LOCKER_DOOR, "closed"));
    } else {
      return (await TELL_ALREADY("closed"));
    }
  } else if (isVerb(V.READ)) {
    await FIXED_FONT_ON();
    tell("    \"S.S. LEVIATHAN\n     STORAGE LOCKER\n   DANGER: EXPLOSIVES!\"\n");
    await FIXED_FONT_OFF();
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The door, which has a sign on it, is ");
    if (hasFlag(LOCKER_DOOR, OPENBIT)) {
      tell("open");
    } else {
      tell("closed");
    }
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

async function SKELETON_F(rarg = false) {
  if (rarg == M_OBJDESC) {
    tell("Some who went down with the ship were in here, where they are nothing more than ");
    await DPRINT(SKELETON);
    tell("s.\n");
    return true;
  } else if (isVerb(V.KILL)) {
    tell("The ");
    await DPRINT(SKELETON);
    tell("s remain dead.\n");
    return true;
  } else if (isVerb(V.MUNG, V.ATTACK, V.TAKE, V.PUSH)) {
    tell("One of the ");
    await DPRINT(SKELETON);
    tell("s falls apart.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.COUNT)) {
    tell("There are about fifty of them. ");
    if (isVerb(V.COUNT)) {
      tell("It's hard to tell exactly.\n");
      return true;
    } else {
      tell("As you look around, you notice that one of the ");
      await DPRINT(SKELETON);
      tell("s has what looks like a ");
      await DPRINT(SCABBARD);
      tell(" at its hip.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SCABBARD_F() {
  let f = 0;
  if (isVerb(V.TAKE)) {
    tell("The ");
    await DPRINT(SCABBARD);
    tell(" is stuck to the ");
    await DPRINT(SKELETON);
    tell(" by encrusted barnacles.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("There is very little of the original leather left to this ");
    await DPRINT(SCABBARD);
    tell(", but barnacles have collected in its place.");
    if (f = first(SCABBARD)) {
      tell(" There is ");
      await APRINT(f);
      tell(" in the ");
      await DPRINT(SCABBARD);
      tell(".");
    }
    return crlf();
  } else if (isVerb(V.OPEN)) {
    return (await TELL_ALREADY("open"));
  } else if (isVerb(V.CLOSE)) {
    tell("It doesn't close.\n");
    return true;
  } else if (isVerb(V.CUT)) {
    return await TELL_BARNACLES();
  } else {
    return false;
  }
}

