async function MCGINTY_F(rarg = false) {
  let obj = 0, pflag = 0;
  if (rarg == M_OBJDESC) {
    if (g.MCGINTY_KNOWS) {
    } else if ((loc(PASSBOOK) == g.PLAYER) && !(await QUEUED$(I_MCGINTY_FOLLOWS.id))) {
      pflag = 1;
      await MCGINTY_WILL_FOLLOW();
    } else if (loc(PASSBOOK) == g.HERE) {
      await MCGINTY_WILL_FOLLOW();
      move(PASSBOOK, MCGINTY);
      pflag = 2;
    }
    if ((await IN_MOTION$(MCGINTY)) || ((await QUEUED$(I_MCGINTY_FOLLOWS.id)) && isVerb(V.WALK, V.FOLLOW) && !(loc(MCGINTY) == loc(g.PLAYER))) || (await TRAITOR_TIME$())) {
      return true;
    } else if (hasFlag(MCGINTY, TOUCHBIT)) {
      await DPRINT(MCGINTY);
      tell(" is here, ");
      if (g.HERE == OUTFITTERS_HQ) {
        tell("talking with the salesman");
      } else {
        tell("smoking his cigar");
      }
      tell(".");
    } else {
      await DPRINT(MCGINTY);
      tell(", a small, nervous man, is ");
      if (loc(MCGINTY) == MCGINTY_HQ) {
        tell("sitting behind a desk");
      } else {
        tell("standing nearby");
      }
      tell(". His lips clamp around a cigar too large for his face.");
      setFlag(MCGINTY, TOUCHBIT);
    }
    if (pflag == 1) {
      await TELL_EYES_NARROW();
    } else if (pflag == 2) {
      (await TELL_TAKE_PASS(" He"));
    }
    crlf();
    return true;
  } else if (rarg == M_CONT) {
    if (isVerb(V.TAKE) && hasFlag(g.PRSO, TAKEBIT)) {
      await DPRINT(MCGINTY);
      tell(" pulls it back. \"I'm not gonna give that to you!\"\n");
      return true;
    } else {
      return false;
    }
  }
  if (g.WINNER == MCGINTY) {
    if (!(loc(MCGINTY) == (await META_LOC(g.PLAYER)))) {
      g.P_CONT = false;
      await TELL_NOT_HERE_TALK();
      return M_FATAL;
    } else if (await TRAITOR_TIME$()) {
      await TELL_IN_MEETING();
      return M_FATAL;
    }
  }
  setFlag(MCGINTY, TOUCHBIT);
  if (isVerb(V.FOLLOW) && (g.PRSO == MCGINTY)) {
    return false;
  } else if (isVerb(V.$CALL) && (await TRAITOR_TIME$())) {
    await TELL_IN_MEETING();
    return true;
  } else if (isVerb(V.HELLO)) {
    g.QCONTEXT = MCGINTY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("\"Howdy.\"\n");
    return true;
  } else if (isVerb(V.GOODBYE)) {
    g.QCONTEXT = MCGINTY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("\"So long.\"\n");
    return true;
  } else if ((isVerb(V.TAKE) && (g.PRSI == MCGINTY)) || (isVerb(V.ASK_FOR) && (g.PRSO == MCGINTY))) {
    if (g.PRSO == MCGINTY) {
      obj = g.PRSI;
    } else {
      obj = g.PRSO;
    }
    if (loc(obj) == MCGINTY) {
      tell("\"I'm not gonna give that to you.\"\n");
    } else {
      tell("\"I don't have that.\"\n");
    }
    return true;
  } else if (isVerb(V.BUY)) {
    if (g.PRSO == FERRY_TOKEN) {
      tell("\"I don't have one. Try the bank.\"\n");
      return true;
    }
  }
  if (isVerb(V.$CALL) && (g.WINNER == g.PLAYER)) {
    return false;
  } else if (!(await GRAB_ATTENTION(MCGINTY))) {
    return true;
  }
  if (isVerb(V.TELL) && (g.PRSO == MCGINTY)) {
    if (g.PRSI == GLOBAL_TREASURE || g.PRSI == g.SAMPLE_TREASURE) {
      if (await TRAITOR_TIME$()) {
        (await JIGS_UP("The Weasel turns and yells, \"Traitor!\" Next thing you know, you've been stabbed."));
      } else if (g.MCGINTY_KNOWS) {
        tell("\"Thanks, but I already know about it.\"\n");
      } else {
        if ((loc(SPEAR_CARRIER) == g.HERE) || (loc(JOHNNY) == g.HERE) || (loc(PETE) == g.HERE) || (loc(WEASEL) == g.HERE)) {
          g.MCGINTY_KNOWS = true;
          await ZERO_ATTENTION(MCGINTY);
          put(get(g.GOAL_TABLES, MCGINTY_C), GOAL_ENABLE, true);
          await DPRINT(MCGINTY);
          tell(" looks delighted with the information.");
          if (loc(MCGINTY) == OUTFITTERS_HQ) {
            await ESTABLISH_GOAL(MCGINTY, MCGINTY_HQ);
            if (loc(JOHNNY) == OUTFITTERS_HQ) {
              await SAY_MCGINTY_KNOWS();
            } else {
              tell(" He thanks you.");
              await TELL_NEED_BOAT();
            }
          } else {
            await ESTABLISH_GOAL(MCGINTY, OUTFITTERS_HQ);
            await ALL_GO_HOME();
            await I_PLOT_NEVER_STARTS();
            disable(await INT(I_SHOVE_OFF.id));
            tell(" \"Excuse me,\" he says. \"I have business to attend to.\"\n");
          }
        } else {
          (await JIGS_UP("\"Thanks for the info, pal, but I better make sure you don't use it.\" He pulls out his gun and shoots."));
        }
      }
      return true;
    }
  } else if (isVerb(V.SHOW) && (g.PRSO == NOTE || g.PRSO == BOOK) && (g.PRSI == MCGINTY)) {
    await PERFORM(V.TELL, MCGINTY, GLOBAL_TREASURE);
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == MCGINTY)) {
    if (await TRAITOR_TIME$()) {
      await TELL_IN_MEETING();
      return M_FATAL;
    } else if (g.PRSI == GLOBAL_TREASURE) {
      tell("\"I'm always looking for ");
      await DPRINT(GLOBAL_TREASURE);
      tell(",\" he says, grinning.\n");
    } else if (g.PRSI == SPEAR_CARRIER) {
      tell("\"He does his job.\"\n");
    } else if (g.PRSI == PETES_PATCH) {
      tell("\"All I know is that Pete wears it.\"\n");
    } else if (g.PRSI == CIGAR) {
      tell("\"Yeah. That's my cigar.\"\n");
    } else if (g.PRSI == HEVLIN) {
      await TELL_NEVER_KNEW();
    } else if (g.PRSI == JOHNNY || g.PRSI == PETE || g.PRSI == WEASEL) {
      tell("\"He's worked for me. He's all right.\"\n");
    } else if (g.PRSI == ME) {
      await TELL_YOURE_DIVER();
    } else if (g.PRSI == MCGINTY) {
      await TELL_KNOW_ME();
    } else if (g.PRSI == PARROT) {
      tell("\"It's the queerest bird I've ever seen.\"\n");
    } else if (g.PRSI == TRAWLER || g.PRSI == SALVAGER) {
      tell("\"She's a nice boat.\"\n");
    } else {
      return false;
    }
    return true;
  }
  if (g.WINNER == MCGINTY) {
    if (g.PRSO == GLOBAL_SELF) {
      g.PRSO = MCGINTY;
    }
    if (g.PRSI == GLOBAL_SELF) {
      g.PRSI = MCGINTY;
    }
    if (isVerb(V.TELL) && (g.PRSO == ME)) {
      return false;
    } else if (isVerb(V.$CALL)) {
      return await TELL_SO_WHAT();
    } else if (isVerb(V.WALK, V.DISEMBARK, V.LEAVE)) {
      tell("\"I'll leave when I'm ready.\"\n");
      return true;
    } else if (isVerb(V.SHOW) && (loc(g.PRSO) == MCGINTY) && (g.PRSI == ME)) {
      g.WINNER = g.PLAYER;
      await PERFORM(V.EXAMINE, g.PRSO);
      return g.WINNER = MCGINTY;
    } else if (isVerb(V.YES, V.NO, V.MAYBE, V.WHAT, V.FIND, V.SSHOW, V.ALARM)) {
      return false;
    } else {
      tell("\"I'd rather not.\"\n");
      return M_FATAL;
    }
  } else {
    return false;
  }
}

