async function MCGINTY_WILL_FOLLOW() {
  let gt = 0;
  if (g.MCGINTY_KNOWS) {
    return false;
  }
  gt = get(g.GOAL_TABLES, MCGINTY_C);
  put(gt, GOAL_ENABLE, false);
  put(gt, GOAL_F, WRECK_13);
  put(gt, ATTENTION, 500);
  disable(await INT(I_MCGINTY.id));
  return enable(await QUEUE(I_MCGINTY_FOLLOWS.id, -1));
}

async function I_MCGINTY_FOLLOWS() {
  let gt = 0, mcg_loc = loc(MCGINTY);
  if ((g.PRESENT_TIME > 810) && !g.ALREADY_FOLLOWED) {
    disable(await INT(I_MCGINTY_FOLLOWS.id));
    put(gt = get(g.GOAL_TABLES, MCGINTY_C), ATTENTION, 0);
    put(gt, GOAL_ENABLE, true);
    g.ALREADY_FOLLOWED = true;
    await ESTABLISH_GOAL(MCGINTY, MCGINTY_HQ);
    return false;
  }
  put(get(g.GOAL_TABLES, MCGINTY_C), ATTENTION, 5);
  if ((g.HERE == OUTFITTERS_HQ) && (mcg_loc == WHARF_ROAD_4)) {
    return await MOVE_PERSON(MCGINTY, OUTFITTERS_HQ);
  } else if (g.HERE == mcg_loc || g.HERE == g.LAST_PLAYER_LOC) {
    return false;
  } else if (mcg_loc == g.LAST_PLAYER_LOC) {
    return false;
  } else if (!(g.LAST_PLAYER_LOC == (await META_LOC(g.LAST_PLAYER_LOC)))) {
    return false;
  } else {
    return await MOVE_PERSON(MCGINTY, g.LAST_PLAYER_LOC);
  }
}

async function CIGAR_F() {
  if (isVerb(V.TAKE)) {
    await DPRINT(MCGINTY);
    tell(" yanks it back, then tenderly clamps it between his teeth.\n");
    return true;
  } else if (isVerb(V.LAMP_ON)) {
    return (await TELL_ALREADY("lit"));
  } else if (isVerb(V.SMELL)) {
    tell("The cigar smells like a burning tire.\n");
    return true;
  } else {
    return false;
  }
}

async function JOHNNY_F(rarg = false) {
  let treas = 0;
  if (rarg == M_OBJDESC) {
    if ((await QUEUED$(I_PENDULUM.id)) && eq(get(await INT(I_PENDULUM.id), C_TICK), -1)) {
      return true;
    } else if (await IN_MOTION$(JOHNNY)) {
      return true;
    } else if ((g.HERE == MM_AFT_DECK || g.HERE == NW_AFT_DECK) && g.WEASEL_APPREHENDED && !(await QUEUED$(I_PENDULUM.id))) {
      await I_JOHNNY(G_REACHED);
    } else if (hasFlag(JOHNNY, TOUCHBIT)) {
      await DPRINT(JOHNNY);
      tell(" is here");
      if (loc(SPEAR_CARRIER) == g.HERE) {
        if (loc(MCGINTY) == g.HERE) {
          tell(", glaring at ");
          await DPRINT(MCGINTY);
        } else if (((g.FM_CTR < 2) || (g.FM_CTR > 4)) && !(g.PRESENT_TIME == 704)) {
          tell(", chatting with the ");
          await DPRINT(SPEAR_CARRIER);
        }
      }
      tell(".\n");
    } else {
      await DPRINT(JOHNNY);
      tell(" is here. Red hair sprouts from his head and from beneath his flannel shirt.\n");
      setFlag(JOHNNY, TOUCHBIT);
    }
    return true;
  } else if (rarg == M_CONT) {
    if (isVerb(V.TAKE) && hasFlag(g.PRSO, TAKEBIT)) {
      tell("Johnny glares down at you. \"Get your hands off of that!\"\n");
      return true;
    } else if ((KNIFE == g.PRSO || KNIFE == g.PRSI) && (!(isVerb(V.EXAMINE, V.FIND, V.ASK_ABOUT)) && !(isVerb(V.ASK_CONTEXT_ABOUT)))) {
      tell("Johnny pulls it back. \"I'm not gonna let you give this to ");
      await DPRINT(WEASEL);
      tell(".\"\n");
      return true;
    } else {
      return false;
    }
  }
  if ((JOHNNY == g.WINNER) && !(eq(await META_LOC(JOHNNY), await META_LOC(g.PLAYER)))) {
    g.P_CONT = false;
    await TELL_NOT_HERE_TALK();
    return M_FATAL;
  }
  setFlag(JOHNNY, TOUCHBIT);
  if (isVerb(V.FOLLOW) && (g.PRSO == JOHNNY)) {
    return false;
  } else if (isVerb(V.TELL) && !g.PRSI) {
    return false;
  } else if (g.MCGINTY_KNOWS || g.JOHNNY_SILENT) {
    await DPRINT(JOHNNY);
    tell(" looks right through you.\n");
    return M_FATAL;
  } else if (isVerb(V.HELLO, V.GOODBYE)) {
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("\"Ahoy, matey.\"\n");
    return true;
  } else if (isVerb(V.BUY)) {
    if (g.PRSO == FERRY_TOKEN) {
      tell("\"Try ");
      await DPRINT(BANK);
      tell(".\"\n");
      return true;
    }
  }
  if (isVerb(V.$CALL) && (g.WINNER == g.PLAYER)) {
    return false;
  } else if (!(await GRAB_ATTENTION(JOHNNY))) {
    return true;
  }
  if (isVerb(V.GIVE, V.SHOW) && (g.PRSO == CHARTS)) {
    tell("\"No thanks. I have my own.\"\n");
    return true;
  } else if ((isVerb(V.SHOW) && (g.PRSO == NOTE)) || (isVerb(V.ASK_ABOUT) && (g.PRSI == NOTE))) {
    tell("\"Yeah. I wrote that.\"\n");
    return true;
  } else if (isVerb(V.GIVE) && ((g.PRSO == ENVELOPE) || (g.PRSO == ID_CARD))) {
    if (!(loc(ID_CARD) == ENVELOPE)) {
      await TELL_RETURNS(JOHNNY);
    }
    await PERFORM(V.SHOW, g.PRSO, JOHNNY);
    return true;
  } else if (isVerb(V.SHOW) && (g.PRSI == JOHNNY)) {
    if ((loc(ID_CARD) == ENVELOPE) && ((g.PRSO == ENVELOPE) || (g.PRSO == ID_CARD))) {
      tell("Johnny takes the card and ");
      await DPRINT(ENVELOPE);
      tell(" and studies them. ");
      if (g.WEASEL_APPREHENDED) {
        await TELL_ALREADY_SHOWN();
        tell(",\" he says, handing the ");
        await DPRINT(ENVELOPE);
        tell(" back.");
      } else if (g.CLUMSILY_HANDLED) {
        tell("\"You trying to frame ");
        await DPRINT(WEASEL);
        tell("?\" He returns the ");
        await DPRINT(ENVELOPE);
        tell(".");
      } else {
        move(ENVELOPE, JOHNNY);
        tell("\"So,\" he muses, \"");
        await DPRINT(WEASEL);
        tell(" is working with ");
        await DPRINT(MCGINTY);
        tell(". I'll take care of him.\"");
        g.WEASEL_BLOWN = true;
        if (loc(WEASEL) == loc(JOHNNY)) {
          await ROUGH_JUSTICE();
        } else if ((loc(WEASEL) == FERRY) || (loc(WEASEL) == GLOBAL_FERRY)) {
          await ESTABLISH_GOAL(JOHNNY, FERRY_LANDING);
        } else {
          await ESTABLISH_GOAL(JOHNNY, await META_LOC(WEASEL));
        }
      }
      crlf();
      return true;
    } else if (g.PRSO == ENVELOPE) {
      if (g.WEASEL_BLOWN) {
        await TELL_ALREADY_SHOWN();
      } else {
        tell("\"It's empty. It don't mean nothing");
        g.CLUMSILY_HANDLED = true;
      }
      tell(".\"\n");
      return true;
    } else if (g.PRSO == ID_CARD) {
      if (g.WEASEL_BLOWN) {
        await TELL_ALREADY_SHOWN();
      } else {
        tell("\"That's ");
        await DPRINT(WEASEL);
        tell("'s. He'll be glad you found it");
        g.CLUMSILY_HANDLED = true;
      }
      tell(".\"\n");
      return true;
    }
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == JOHNNY)) {
    if (g.PRSI == GLOBAL_TREASURE || g.PRSI == g.SAMPLE_TREASURE || g.PRSI == SHARK) {
      if (loc(MCGINTY) == g.HERE) {
        await MCGINTY_AND_TREASURE(GLOBAL_TREASURE);
      } else if (!(await ENABLED$(I_JOHNNY.id)) || !g.SAMPLE_TREASURE) {
        tell("Red scowls. \"What ");
        await DPRINT(GLOBAL_TREASURE);
        tell("?\"\n");
      } else if (g.SM_CTR < 2) {
        tell("\"All in good time.\"\n");
      } else if ((g.TM_CTR < 7) || (loc(WEASEL) == g.HERE) || (loc(PETE) == g.HERE) || (loc(SPEAR_CARRIER) == g.HERE)) {
        tell("\"I told you. I found a ");
        await DPRINT(g.SAMPLE_TREASURE);
        tell(" while I was cleaning a shark.\"\n");
      } else if (g.PRSI == SHARK) {
        tell("\"I made that up.\"\n");
      } else {
        tell("\"Hevlin gave it to me.\"\n");
      }
    } else if (g.PRSI == BOOK) {
      if ((g.TM_CTR < 7) || (loc(WEASEL) == g.HERE) || (loc(PETE) == g.HERE) || (loc(SPEAR_CARRIER) == g.HERE)) {
        return false;
      } else {
        tell("\"That's the one Hevlin gave you.\"\n");
      }
    } else if (g.PRSI == PETES_PATCH) {
      tell("\"Pete's worn it a long time.\"\n");
    } else if (g.PRSI == HEVLIN) {
      tell("\"He was an old friend of mine.\"\n");
    } else if (g.PRSI == SPEAR_CARRIER) {
      tell("\"You know him as well as I do.\"\n");
    } else if (g.PRSI == ME) {
      await TELL_YOURE_DIVER();
    } else if (g.PRSI == WEASEL) {
      tell("\"The Weasel? ");
      if (g.WEASEL_BLOWN) {
        tell("Lower than a sea slug...\"");
      } else if (loc(WEASEL) == g.HERE) {
        tell("He's my pal.\"");
        (await TELL_FERRY_KLUDGE("grins"));
      } else {
        tell("I wouldn't trust him farther than I could throw a whale! But he's a great one-man crew.\"");
      }
      crlf();
    } else if (g.PRSI == MCGINTY) {
      if (loc(MCGINTY) == g.HERE) {
        printC(34);
        await DPRINT(MCGINTY);
        tell("'s one of my favorite people to work for!\"\n");
      } else {
        tell("\"That man would sell his mother for a profit!\"\n");
      }
    } else if (g.PRSI == PETE) {
      if (loc(PETE) == g.HERE) {
        tell("Johnny leans over and mutters, ");
      }
      tell("\"Pete's no genius, but he's dependable. He got a bad name 'cause of what happened, him serving his mates rats for mess. But he'll never make that mistake again!\"\n");
    } else if (g.PRSI == JOHNNY) {
      await TELL_KNOW_ME();
    } else if (g.PRSI == PARROT) {
      tell("\"It's what makes ");
      await DPRINT(SHANTY);
      tell(" what it is.\"\n");
    } else if (g.PRSI == TRAWLER || g.PRSI == SALVAGER) {
      tell("\"It's one of Outfitters' boats.\"\n");
    } else if (g.PRSI == LINE_HACK) {
      tell(S(g.LINE_STR), "\n");
    } else {
      return false;
    }
    return true;
  }
  if (g.WINNER == JOHNNY) {
    if (g.PRSO == GLOBAL_SELF) {
      g.PRSO = JOHNNY;
    }
    if (g.PRSI == GLOBAL_SELF) {
      g.PRSI = JOHNNY;
    }
    if (loc(MCGINTY) == g.HERE) {
      if (g.PRSO == GLOBAL_TREASURE || g.PRSO == g.SAMPLE_TREASURE) {
        treas = g.PRSO;
      } else if (g.PRSI == g.SAMPLE_TREASURE || g.PRSI == GLOBAL_TREASURE) {
        treas = g.PRSI;
      }
      if (treas) {
        await MCGINTY_AND_TREASURE(treas);
        return true;
      }
    }
    if (isVerb(V.TELL) && (g.PRSO == ME)) {
      return false;
    } else if (isVerb(V.$CALL)) {
      return await TELL_SO_WHAT();
    } else if (isVerb(V.SHOW) && (loc(g.PRSO) == JOHNNY) && (g.PRSI == ME)) {
      g.WINNER = g.PLAYER;
      await PERFORM(V.EXAMINE, g.PRSO);
      return g.WINNER = JOHNNY;
    } else if (isVerb(V.YES, V.NO, V.MAYBE, V.LATITUDE, V.LONGITUDE, V.WHAT, V.FIND, V.SSHOW, V.ALARM)) {
      return false;
    } else {
      tell("\"I'll do what I want.\"\n");
      return M_FATAL;
    }
  } else {
    return false;
  }
}

async function MCGINTY_AND_TREASURE(tre) {
  await MCGINTY_WILL_FOLLOW();
  tell("Johnny looks at ");
  await DPRINT(MCGINTY);
  tell(" and then at you. \"What ");
  await DPRINT(tre);
  tell("?\"\n");
  return true;
}

