async function I_FIRST_MEETING() {
  if (g.FM_CTR == 5) {
    disable(await INT(I_FIRST_MEETING.id));
    return false;
  } else if ((loc(JOHNNY) == SHANTY) && (loc(PETE) == SHANTY) && eq(await META_LOC(g.PLAYER), SHANTY)) {
    if (g.FM_CTR == 0) {
      if (g.PRESENT_TIME > 535) {
        await I_PLOT_NEVER_STARTS();
        disable(await INT(I_FIRST_MEETING.id));
        return false;
      }
      g.QCONTEXT = JOHNNY;
      g.QCONTEXT_ROOM = g.HERE;
      tell("\"Sit down and we'll talk,\" ");
      await DPRINT(JOHNNY);
      tell(" says.\n");
      return true;
    } else if (g.FM_CTR == 1) {
      if (loc(WEASEL) == SHANTY) {
        g.FM_CTR = 2;
        return await I_FIRST_MEETING();
      } else if (g.WAITING_FOR_WEASEL) {
        if (g.PRESENT_TIME > 525) {
          disable(await INT(I_FIRST_MEETING.id));
          await I_PLOT_NEVER_STARTS();
          g.QCONTEXT = JOHNNY;
          g.QCONTEXT_ROOM = g.HERE;
          tell("Pete looks at Johnny and says, \"Weasel ain't gonna show.\"\n\"Guess not,\" replies Johnny. \"Without ");
          await DPRINT(WEASEL);
          tell(", there's no deal. Who knows what that creep is up to?\"\n");
          return true;
        } else {
          return false;
        }
      } else {
        g.QCONTEXT = JOHNNY;
        g.QCONTEXT_ROOM = g.HERE;
        tell("Johnny says, \"When ");
        await DPRINT(WEASEL);
        tell(" shows, I'll tell ya what we got.\"\n");
        return g.WAITING_FOR_WEASEL = true;
      }
    } else if (g.BLOOD_ALCOHOL > 10) {
      disable(await INT(I_FIRST_MEETING.id));
      await I_PLOT_NEVER_STARTS();
      tell("Pete turns to Johnny and says, \"This joker's drunk!\"\n\"Yeah,\" Johnny says. He looks at you. \"Some diver! We'll find someone else.\"\n");
      return true;
    } else if (g.FM_CTR == 2) {
      g.QCONTEXT = JOHNNY;
      g.QCONTEXT_ROOM = g.HERE;
      tell("At Pete's request, ");
      await DPRINT(WEASEL);
      tell(" joins you. Johnny then whispers that he's come across some sunken ");
      await DPRINT(GLOBAL_TREASURE);
      tell(".\n");
      g.FM_CTR = 3;
      g.I_WAIT_RTN = I_FIRST_MEETING.id;
      return g.I_WAIT_DURATION = 2;
    } else if (g.FM_CTR == 3) {
      if (g.I_WAIT_FLAG) {
        tell("Unfortunately, this interrupts Johnny's explanation of what the meeting is about.\n");
        return g.I_WAIT_DURATION = 2;
      } else if ((g.I_WAIT_DURATION > 0) && (g.I_WAIT_RTN == I_FIRST_MEETING.id)) {
        return false;
      } else {
        g.QCONTEXT = JOHNNY;
        g.QCONTEXT_ROOM = g.HERE;
        tell("Johnny explains that they need more money to get started. They chose you because they know you've salted some money away and you're a great diver. He asks if you're interested in the deal.\n");
        return g.FM_CTR = 4;
      }
    } else if (g.FM_CTR == 4) {
      if ((g.PRESENT_TIME > 539) && !(isVerb(V.YES, V.NO))) {
        g.QCONTEXT = JOHNNY;
        g.QCONTEXT_ROOM = g.HERE;
        await I_PLOT_NEVER_STARTS();
        tell("Pete turns to Johnny. \"We don't want anyone who can't decide.\"\n\"Right,\" says Johnny. \"We'll find someone else.\" He turns to you. \"Say a word about this and you're history!\"\n");
        return true;
      } else {
        g.QCONTEXT = JOHNNY;
        g.QCONTEXT_ROOM = g.HERE;
        tell("\"Well, what is it? Yes or no?\" Pete asks anxiously.\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function SAMPLE_TREASURE_F() {
  if (isVerb(V.TAKE) || (isVerb(V.ASK_FOR) && (g.PRSO == JOHNNY))) {
    if (loc(MCGINTY) == g.HERE) {
      await PERFORM(V.TELL, MCGINTY, g.SAMPLE_TREASURE);
      return true;
    } else {
      tell("Red pulls it back. \"If we get the loot, there'll be plenty for all.\"\n");
      return true;
    }
  } else if (isVerb(V.TURN)) {
    await DPRINT(JOHNNY);
    tell(" has it.\n");
    return true;
  } else {
    return false;
  }
}

async function I_SECOND_MEETING() {
  if ((g.PRESENT_TIME > 585) && ((g.SM_CTR < 2) || (g.HOW_HUNGRY > 3))) {
    await ALL_GO_HOME();
    await I_PLOT_NEVER_STARTS();
    g.SM_CTR = 4;
  }
  if (g.SM_CTR == 4) {
    return disable(await INT(I_SECOND_MEETING.id));
  } else if (!(g.HERE == WINDING_ROAD_1)) {
    return disable(await INT(I_SECOND_MEETING.id));
  } else if ((g.SM_CTR > 1) && ((loc(MCGINTY) == WINDING_ROAD_1) || (loc(MCGINTY) == WINDING_ROAD_2))) {
    return (await JIGS_UP("Pete spots McGinty, who is near enough to overhear! While Johnny chases McGinty, Pete accuses you of bringing McGinty along. Before you respond, the Weasel plunges his knife into your heart."));
  } else if (g.SM_CTR < 2) {
    if ((loc(WEASEL) == WINDING_ROAD_1) && (loc(JOHNNY) == WINDING_ROAD_1) && (loc(PETE) == WINDING_ROAD_1)) {
      g.SM_CTR = 2;
      await I_SECOND_MEETING();
      return true;
    } else if (g.SM_CTR == 0) {
      if (loc(JOHNNY) == WINDING_ROAD_1) {
        g.SM_CTR = 1;
        g.QCONTEXT = JOHNNY;
        g.QCONTEXT_ROOM = g.HERE;
        tell("Johnny says, \"We'll start when everyone's here.\"\n");
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (g.BLOOD_ALCOHOL > 10) {
    g.SM_CTR = 4;
    disable(await INT(I_SECOND_MEETING.id));
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    await ALL_GO_HOME();
    await I_PLOT_NEVER_STARTS();
    tell("\"I won't risk everything on a drunk diver!\" ");
    await DPRINT(WEASEL);
    tell(" says.\n\"You're right,\" says Johnny. \"We're calling this off.\"\n");
    return true;
  } else if (g.SM_CTR == 2) {
    g.WRECK_FOUND = random(2);
    if (g.WRECK_FOUND == 1) {
      g.SAMPLE_TREASURE = GOLD_COIN;
    } else {
      g.SAMPLE_TREASURE = DINNER_PLATE;
    }
    putProp(g.SAMPLE_TREASURE, P.ACTION, SAMPLE_TREASURE_F.id);
    move(g.SAMPLE_TREASURE, JOHNNY);
    g.P_IT_OBJECT = g.SAMPLE_TREASURE;
    g.SM_CTR = 3;
    g.I_WAIT_DURATION = 6;
    g.I_WAIT_RTN = I_SECOND_MEETING.id;
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("Johnny nods, then pulls out ");
    await APRINT(g.SAMPLE_TREASURE);
    tell(" he says he came across while on a shark hunt.\n");
    return true;
  } else if (g.SM_CTR == 3) {
    if (g.I_WAIT_FLAG) {
      tell("This interrupts Johnny's explanation, which makes him angry.\n");
      return g.I_WAIT_DURATION = 6;
    } else if ((g.I_WAIT_DURATION > 0) && (g.I_WAIT_RTN == I_SECOND_MEETING.id)) {
      return false;
    } else {
      disable(await INT(I_SECOND_MEETING.id));
      enable(await QUEUE(I_OTHERS_MEET.id, 705 - g.PRESENT_TIME));
      g.SM_CTR = 4;
      g.MEETINGS_COMPLETED = 2;
      put(g.MOVEMENT_GOALS, JOHNNY_C, g.JOHNNY_CONTINUES_TABLE);
      await IMOVEMENT(JOHNNY, I_JOHNNY.id);
      await RATING_UPD(20);
      g.QCONTEXT = JOHNNY;
      g.QCONTEXT_ROOM = g.HERE;
      crlf();
      tell("\"We're not sure which wreck to salvage,\" Johnny says. \"Since you're joining up, we're hoping you'll identify where the ");
      await DPRINT(g.SAMPLE_TREASURE);
      tell(" came from, and then do the dive for us. I'll captain, Pete will cook, and ");
      await DPRINT(WEASEL);
      tell(" will crew.\n\nJohnny winks at you. \"We'll need you to supply the minutes of longitude and latitude of the wreck. Get $500 and meet me at Point Lookout at 10:45. Then we'll provision the boat.\"\n\nHe turns to the others. \"We'll meet in ");
      await DPRINT(SHANTY);
      tell(" at 11:45 to discuss final arrangements.\n\n\"We're all in this now,\" Johnny says to the group. \"I'm not gonna chance this operation if one of you doesn't show. We need everyone to pull this off. If anyone tries anything stupid, you won't live to regret it.\"\n");
      return true;
    }
  } else {
    return false;
  }
}

async function I_THIRD_MEETING() {
  let jmg = 0;
  if (!(g.HERE == POINT_LOOKOUT)) {
    disable(await INT(I_THIRD_MEETING.id));
    return false;
  } else if (loc(JOHNNY) == POINT_LOOKOUT) {
    if (g.TM_CTR < 6) {
      g.TM_CTR = g.TM_CTR + 1;
    }
  } else {
    return false;
  }
  if (loc(MCGINTY) == POINT_LOOKOUT) {
    return (await JIGS_UP("Johnny glares at McGinty. \"Trying to cash in on my work again, huh? You probably killed Hevlin, too!\" And with that, he pushes McGinty off the cliff.\n\n\"I can't leave witnesses,\" he mumbles. Before you can react, you're on your way down to join what's left of McGinty."));
  } else if ((loc(MCGINTY) == OCEAN_ROAD_3) && !(await IN_MOTION$(MCGINTY))) {
    return (await JIGS_UP("Johnny sees McGinty on the road. \"You brought McGinty, you traitor! You probably killed Hevlin, too!\" A moment later, you're falling down to the rocks."));
  } else if (g.TM_CTR == 1) {
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("Johnny turns toward you. \"Well? Did you bring the money?\"\n");
    return true;
  } else if (g.BLOOD_ALCOHOL > 10) {
    return (await JIGS_UP("Johnny stares at you in disgust. \"A drunk diving for us? You'll probably tell McGinty, too. I'll make sure you don't.\" He pushes you off the cliff. Although you feel no pain, your landing is fatal."));
  } else if (g.TM_CTR == 4) {
    tell("Johnny glares at you as if you were a sea slug.\n");
    return true;
  } else if (g.TM_CTR == 5) {
    return (await JIGS_UP("Johnny looks disgusted. \"No money? You probably told McGinty already. Traitor!\" He pushes you off the cliff, and you scream as the pointy rocks rush up to meet you."));
  } else if (g.TM_CTR == 6) {
    g.TM_CTR = 7;
    await RATING_UPD(20);
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    crlf();
    tell("\"Glad you're with us. Since you're okay, I'll level with you. Before Hevlin died, he told me he gave you the book. He also said you could handle this job. He's the one who gave me the ");
    await DPRINT(g.SAMPLE_TREASURE);
    tell(". I didn't want to say anything in front of Pete and ");
    await DPRINT(WEASEL);
    tell(" just in case.\n\n\"We're gonna need a boat, but I don't know which one. If you need deep-sea diving gear, it'll have to be the ");
    await DPRINT(SALVAGER);
    tell(". Is the ");
    await DPRINT(GLOBAL_TREASURE);
    tell(" more than 200 feet deep?\"\n");
    return true;
  } else if (g.TM_CTR == 7) {
    if (g.PRESENT_TIME > 675) {
      (await JIGS_UP("Johnny looks disgusted. \"I can't wait all day...\" You feel a shove and then find yourself on your way down to the rocks below."));
    }
    g.QCONTEXT = JOHNNY;
    g.QCONTEXT_ROOM = g.HERE;
    tell("Johnny looks impatient. \"Don't confuse things. A yes or no will do.\"\n");
    return true;
  } else if (g.TM_CTR == 8) {
    await ESTABLISH_GOAL(JOHNNY, OUTFITTERS_HQ);
    put(g.MOVEMENT_GOALS, JOHNNY_C, g.JOHNNY_COMPLETES_TABLE);
    jmg = get(g.MOVEMENT_GOALS, JOHNNY_C);
    put(jmg, MG_TIME, 838 - g.PRESENT_TIME);
    await IMOVEMENT(JOHNNY, I_JOHNNY.id);
    disable(await INT(I_THIRD_MEETING.id));
    g.MEETINGS_COMPLETED = 3;
    tell("\"We'll rent the ");
    await DPRINT(g.SHIP_CHOSEN);
    tell(". Let's go get what we need.\"\n");
    return true;
  } else {
    return false;
  }
}

async function I_EQUIP() {
  let mcg_gt = 0, v_ = false;
  if (loc(g.PLAYER) == OUTFITTERS_HQ) {
    if (loc(MCGINTY) == OUTFITTERS_HQ) {
      g.WARNING_CTR = g.WARNING_CTR + 1;
      if (g.WARNING_CTR == 7) {
        tell("Johnny leans over and whispers, \"Let's wait out McGinty. He should leave soon.\"\n");
        v_ = true;
      }
      if (g.I_WAIT_DURATION > 0) {
        g.I_WAIT_DURATION = 0;
        g.I_WAIT_RTN = false;
        tell("Johnny ends his conversation, and ");
        await DPRINT(MCGINTY);
        tell(" asks the salesman some questions.\n");
        return true;
      } else if (get(mcg_gt = get(g.GOAL_TABLES, MCGINTY_C), GOAL_ENABLE) && eq(get(mcg_gt, GOAL_F), MCGINTY_HQ)) {
        if (!g.MCGINTY_KNOWS) {
          g.MCGINTY_MEETS_WEASEL = true;
        }
        g.I_WAIT_DURATION = 9;
        g.I_WAIT_RTN = I_EQUIP.id;
        return false;
      } else if (isVerb(V.BUY, V.RENT) && !(g.PRSO == FERRY_TOKEN)) {
        g.MCGINTY_KNOWS = true;
        disable(await INT(I_MCGINTY_FOLLOWS.id));
        disable(await INT(I_EQUIP.id));
        move(MCGINTY, WHARF_ROAD_4);
        await ESTABLISH_GOAL(MCGINTY, MCGINTY_HQ);
        await DPRINT(MCGINTY);
        tell(" grins as he realizes what you're up to.");
        return await SAY_MCGINTY_KNOWS();
      } else if (g.PRESENT_TIME > 699) {
        if (loc(JOHNNY) == OUTFITTERS_HQ) {
          await ESTABLISH_GOAL(JOHNNY, SHANTY);
          tell("Johnny glares at ");
          await DPRINT(MCGINTY);
          tell(" and then at his watch. \"There's no way.\" He turns to you. \"Forget it. We can't get this done in time.\"\n");
          return true;
        } else {
          disable(await INT(I_MCGINTY_FOLLOWS.id));
          await ESTABLISH_GOAL(MCGINTY, MCGINTY_HQ);
          disable(await INT(I_EQUIP.id));
          await DPRINT(MCGINTY);
          tell(" turns to the salesman. \"I think... yeah! I will need that boat after all.\" He turns to you and grins.\n");
          return true;
        }
      } else if (!(isVerb(V.WAIT, V.WAIT_FOR) || isVerb(V.LOOK, V.WALK))) {
        tell("Johnny glances nervously at ");
        await DPRINT(MCGINTY);
        tell(".\n");
        return true;
      } else {
        return v_;
      }
    } else if (g.MCGINTY_KNOWS) {
      disable(await INT(I_EQUIP.id));
      return false;
    } else if (g.I_WAIT_FLAG) {
      tell("Johnny seems unhappy to have his conversation interrupted.\n");
      return g.I_WAIT_DURATION = 9;
    } else if (g.I_WAIT_RTN == I_EQUIP.id) {
      if (g.I_WAIT_DURATION > 0) {
        return false;
      } else {
        await ESTABLISH_GOAL(JOHNNY, SHANTY);
        enable(await QUEUE(I_SHOVE_OFF.id, 870 - g.PRESENT_TIME));
        disable(await INT(I_EQUIP.id));
        if (g.SHIP_CHOSEN == TRAWLER) {
          g.AMT_OWED = 50 + random(50);
        } else {
          g.AMT_OWED = 400 + random(50);
        }
        g.JOHNNY_MADE_DEAL = true;
        await RATING_UPD(20);
        tell("Johnny hands him a list and the salesman quotes a price. Johnny gives him the money he has, then says to you, \"You'll need to chip in $", N(g.AMT_OWED), " plus the money for your stuff. We'll leave on the ");
        await DPRINT(g.SHIP_CHOSEN);
        tell(" at high tide.\"\n\nHe tells the ");
        await DPRINT(SPEAR_CARRIER);
        tell(", \"Deliver the stuff half an hour before high tide.\" He turns back to you. \"Better be on board then to watch the stuff.\"\n");
        return true;
      }
    } else if (!(loc(MCGINTY) == WHARF_ROAD_4)) {
      g.I_WAIT_DURATION = 9;
      g.I_WAIT_RTN = I_EQUIP.id;
      return false;
    } else {
      return false;
    }
  } else {
    g.I_WAIT_DURATION = 0;
    if (get(await INT(I_EQUIP.id), C_TICK) < (-15)) {
      disable(await INT(I_EQUIP.id));
      if (loc(JOHNNY) == OUTFITTERS_HQ) {
        await ESTABLISH_GOAL(JOHNNY, SHANTY);
      }
      await I_PLOT_NEVER_STARTS();
      return false;
    } else {
      return false;
    }
  }
}

async function TELL_NEED_BOAT() {
  tell(" \"We will need that boat after all,\" he says to the salesman as he leaves.\n");
  return true;
}

