async function TELL_LINE_SWINGS() {
  tell("The ");
  await DPRINT(SAFETY_LINE);
  tell(" from above swings in from the ");
  if (g.LINE_LOC_INC == 1) {
    tell("south");
  } else {
    tell("north");
  }
  tell(".\n");
  return true;
}

async function I_CASE_LEAK() {
  let already = false;
  g.WATER_IN_CASE = g.WATER_IN_CASE + 1;
  if (g.WATER_IN_CASE > 9) {
    if (hasFlag(STAMPS, RMUNGBIT)) {
      already = true;
    }
    setFlag(STAMPS, RMUNGBIT);
    disable(await INT(I_CASE_LEAK.id));
  }
  if (loc(GLASS_CASE) == g.PLAYER) {
    tell("The water level in the ");
    await DPRINT(GLASS_CASE);
    tell(" rises.");
    if (hasFlag(STAMPS, RMUNGBIT) && !already) {
      tell(" As it reaches the stamps, it soaks them.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function I_DRILL() {
  setFlag(BATTERY, RMUNGBIT);
  g.DRILL_POWERED = false;
  disable(await INT(I_DRILL.id));
  tell("The ");
  await DPRINT(DRILL);
  tell(" sputters, and the bit stops turning.\n");
  return true;
}

async function I_AIR_SUPPLY() {
  if (eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C) && (loc(AIR_TANK) == g.PLAYER) && !(await AIRTIGHT_ROOM$())) {
    g.AIR_LEFT = g.AIR_LEFT - div(g.DEPTH + 33, 44);
    if (g.AIR_LEFT < 1) {
      return (await JIGS_UP("You've used all your air."));
    } else if (g.AIR_LEFT < 15) {
      tell("Your air supply is dangerously low.\n");
      if (g.WAITED$ == 1) {
        return true;
      } else {
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_MM_COMPRESSOR() {
  enable(await QUEUE(I_LAST_GASP.id, 10));
  if (eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C)) {
    tell("You have to breathe harder. Maybe you'd better surface.\n");
    return M_FATAL;
  } else {
    return false;
  }
}

async function I_LAST_GASP() {
  if (eq(getProp(g.HERE, P.LINE), UNDERWATER_LINE_C)) {
    return (await JIGS_UP("There's not enough air to breathe!"));
  } else {
    return disable(await QUEUE(I_LAST_GASP.id, 1));
  }
}

async function I_PLOT_NEVER_STARTS() {
  disable(await INT(I_JOHNNY.id));
  disable(await INT(I_PETE.id));
  if (loc(WEASEL) == SHANTY) {
    disable(await INT(I_WEASEL.id));
  }
  g.FM_CTR = 5;
  return false;
}

async function I_ENDIT() {
  if (getProp(g.HERE, P.LINE) < UNDERWATER_LINE_C) {
    return (await JIGS_UP("You suddenly find Red's hands around your throat as he makes a comment about hating cowards and Hevlin being wrong."));
  } else {
    return false;
  }
}

